//! Units, buildings and technologies by ID, with their costs and English names, from
//! `data/game_data.csv` (generated by `tools/update_game_data.py`, sources in
//! `data/SOURCES.md`). Logic works on IDs; names are for display only.
use crate::replay::ResourceCost;
use std::collections::HashMap;
use std::sync::OnceLock;

/// Technology IDs of the age-ups.
pub const FEUDAL_AGE_TECH: u32 = 101;
pub const CASTLE_AGE_TECH: u32 = 102;
pub const IMPERIAL_AGE_TECH: u32 = 103;
/// Building ID of the Castle.
pub const CASTLE_BUILDING: u32 = 82;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Kind {
    Unit,
    Building,
    Tech,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::Unit => "unit",
            Kind::Building => "building",
            Kind::Tech => "tech",
        }
    }
}

#[derive(Debug, Clone)]
pub struct Entry {
    pub name: String,
    pub cost: ResourceCost,
}

/// Unit and building IDs share one namespace in the game, technologies have their own.
pub struct GameData {
    entries: HashMap<(Kind, u32), Entry>,
}

impl GameData {
    fn parse(content: &str) -> Result<Self, String> {
        let mut entries = HashMap::new();
        let mut rdr = csv::Reader::from_reader(content.as_bytes());
        for record in rdr.records() {
            let r = record.map_err(|e| e.to_string())?;
            let num = |i: usize| -> Result<u32, String> {
                r.get(i)
                    .unwrap_or("")
                    .parse()
                    .map_err(|_| format!("bad number in column {} of {:?}", i, r))
            };
            let kind = match r.get(0) {
                Some("unit") => Kind::Unit,
                Some("building") => Kind::Building,
                Some("tech") => Kind::Tech,
                other => return Err(format!("unknown kind {:?}", other)),
            };
            let entry = Entry {
                name: r.get(2).unwrap_or("").to_string(),
                cost: ResourceCost {
                    food: num(3)?,
                    wood: num(4)?,
                    gold: num(5)?,
                    stone: num(6)?,
                },
            };
            if entries.insert((kind, num(1)?), entry).is_some() {
                return Err(format!("duplicate {} {}", kind.as_str(), num(1)?));
            }
        }
        Ok(GameData { entries })
    }

    /// The table embedded in the binary.
    pub fn get() -> &'static GameData {
        static DATA: OnceLock<GameData> = OnceLock::new();
        DATA.get_or_init(|| {
            GameData::parse(include_str!("../data/game_data.csv"))
                .expect("data/game_data.csv is invalid")
        })
    }

    pub fn lookup(&self, kind: Kind, id: u32) -> Option<&Entry> {
        self.entries.get(&(kind, id))
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn entry(kind: Kind, id: u32) -> &'static Entry {
        GameData::get()
            .lookup(kind, id)
            .unwrap_or_else(|| panic!("{} {} missing", kind.as_str(), id))
    }

    #[test]
    fn table_loads_with_names() {
        let data = GameData::get();
        assert!(data.len() > 500);
        assert!(data.entries.values().all(|e| !e.name.trim().is_empty()));
    }

    #[test]
    fn known_entries() {
        let militia = entry(Kind::Unit, 74);
        assert_eq!(militia.name, "Militia");
        assert_eq!((militia.cost.food, militia.cost.gold), (50, 20));
        assert_eq!(entry(Kind::Unit, 83).name, "Villager");
        assert_eq!(entry(Kind::Building, CASTLE_BUILDING).name, "Castle");
        assert_eq!(entry(Kind::Building, 109).name, "Town Center");
        for (id, name, food) in [
            (FEUDAL_AGE_TECH, "Feudal Age", 500),
            (CASTLE_AGE_TECH, "Castle Age", 800),
            (IMPERIAL_AGE_TECH, "Imperial Age", 1000),
        ] {
            let tech = entry(Kind::Tech, id);
            assert_eq!((tech.name.as_str(), tech.cost.food), (name, food));
        }
        // Unit upgrades are technologies.
        assert_eq!(entry(Kind::Tech, 100).name, "Crossbowman");
    }
}
